import { z } from 'zod';

import { WorkspaceStates } from '@qe/domain';

/** Workspace ids are UUIDs (v7, generated by the control plane). */
export const WorkspaceId = z.uuid();

/** Lower-case letters, digits and single hyphens; unique per owner. */
export const WorkspaceName = z
  .string()
  .min(3)
  .max(63)
  .regex(/^[a-z0-9]+(?:-[a-z0-9]+)*$/, 'lower-case letters, digits and single hyphens');

export const TemplateId = z.string().regex(/^tpl_[a-z0-9_]{1,60}$/);

export const ResourceProfiles = ['small', 'standard', 'large'] as const;
export const ResourceProfile = z.enum(ResourceProfiles);

/** Only https Git URLs; credentials in the URL are refused (05_API_CONTRACTS §2.2). */
export const GitSource = z.object({
  url: z
    .url({ protocol: /^https$/ })
    .max(2048)
    .refine(
      (u) => !URL.canParse(u) || (!new URL(u).username && !new URL(u).password),
      'must not contain credentials',
    ),
  ref: z
    .string()
    .min(1)
    .max(255)
    .regex(/^[A-Za-z0-9._/-]+$/),
});

export const CreateWorkspaceRequest = z.strictObject({
  name: WorkspaceName,
  templateId: TemplateId,
  git: GitSource.optional(),
  resources: z.strictObject({ profile: ResourceProfile }).optional(),
});
export type CreateWorkspaceRequest = z.infer<typeof CreateWorkspaceRequest>;

export const UpdateWorkspaceRequest = z
  .strictObject({ name: WorkspaceName.optional(), git: GitSource.nullable().optional() })
  .refine((u) => u.name !== undefined || u.git !== undefined, 'nothing to update');
export type UpdateWorkspaceRequest = z.infer<typeof UpdateWorkspaceRequest>;

export const Workspace = z.object({
  id: WorkspaceId,
  name: WorkspaceName,
  state: z.enum(WorkspaceStates),
  templateId: TemplateId,
  ownerId: z.uuid(),
  ideUrl: z.string(),
  resources: z.object({ profile: ResourceProfile }),
  git: GitSource.nullable(),
  lastActiveAt: z.iso.datetime().nullable(),
  createdAt: z.iso.datetime(),
  updatedAt: z.iso.datetime(),
});
export type Workspace = z.infer<typeof Workspace>;

export const ListWorkspacesQuery = z.strictObject({
  limit: z.coerce.number().int().min(1).max(100).default(50),
});
export type ListWorkspacesQuery = z.infer<typeof ListWorkspacesQuery>;

export const WorkspaceList = z.object({ items: z.array(Workspace) });
export type WorkspaceList = z.infer<typeof WorkspaceList>;

export const WorkspaceTemplate = z.object({
  id: TemplateId,
  displayName: z.string(),
  defaultProfile: ResourceProfile,
});
export type WorkspaceTemplate = z.infer<typeof WorkspaceTemplate>;

export const WorkspaceTemplateList = z.object({ items: z.array(WorkspaceTemplate) });

export const WorkspaceIdParams = z.strictObject({ id: WorkspaceId });

/** Server-sent event on `GET /api/v1/workspaces/{id}/events` (Phase 05 §5.4). */
export const WorkspaceStateEvent = z.object({
  id: WorkspaceId,
  state: z.enum(WorkspaceStates),
  reason: z.string().nullable(),
});
export type WorkspaceStateEvent = z.infer<typeof WorkspaceStateEvent>;
